    st_stox_32: 'jedes Geheimnis, jeden Brand',
    st_stox_33: 'was auch immer noch verborgen liegt',
    st_stox_34: 'ist draußen, hinter diesen Mauern',
    st_stox_35: 'in den Regionen, in den Stoxeln',
    st_stox_36: 'in dem, was übrig bleibt, wenn etwas fällt',
    st_stox_37: 'Alle Aufzeichnungen zeigen nach innen',
