    st_stox_40: 'verstand ihn bis in jeden Teil',
    st_stox_41: 'Eine Wahrheit bleibt nicht vergraben',
    st_stox_42: 'nicht vor jemandem, der nicht aufhört',
    st_stox_43: 'er kann nicht finden, wer oder warum',
    st_stox_44: 'doch er weiß, wo die Antworten liegen',
    st_stox_45: 'Das Archiv ging die Antworten aus',
