    st_stox_5: 'jede Notiz, jedes Vermessungsprotokoll',
    st_stox_50: 'er wird sie finden, er sucht nicht länger',
    st_stox_51: 'jede Seite, die er lernte, war eine angelehnte Tür',
    st_stox_52: 'jetzt ist er Papier los',
