    st_stox_54: 'Das Archiv hütete seine Geheimnisse dreihundert Jahre lang',
    st_stox_55: 'jetzt tritt er hinaus daran vorbei, lässt die Ängste zurück',
    st_stox_56: 'er tauscht seine Seiten gegen die Hand eines Lehrers',
    st_stox_57: 'bereit zu lernen, was er nicht verstehen kann',
