    st_stox_7: 'alles, was die Ersten Kartografen',
    st_stox_8: 'jemals zurückließen',
    st_stox_9: 'Er hat alles durchgesehen',
    st_syla_1: 'Geboren unter dem Normalenhain',
    st_syla_10: 'jeden Morgen, nie im Irrtum',
    st_syla_11: 'und die Vögel singen dieselben Töne',
    st_syla_12: 'gleicher Ast, gleiche Zeit, gleiches Lied',
    st_syla_13: 'Eichhörnchen horten an derselben Stelle',
    st_syla_14: 'Hirsche trinken aus dem stehenden Bach',
    st_syla_15: 'etwas zieht am Wilden',
    st_syla_16: 'saugt den lebendigen Traum aus',
    st_syla_17: 'Sie prüft die Instrumente ihrer Eltern',
    st_syla_18: 'die Zahlen geben ihr recht',
    st_syla_19: 'sie sandten Gildenberichte',
    st_syla_2: 'wo die Glockenkurve den Stein formt',
    st_syla_20: 'doch niemand antwortet hier',
    st_syla_21: 'Sie zieht die Linie',
    st_syla_22: 'sie markiert die Steigung',
    st_syla_23: 'und gegen Ende biegt sie zu weit',
    st_syla_24: 'das war nie Hintergrundrauschen',
    st_syla_25: 'etwas drängt aus der Dunkelheit',
    st_syla_26: 'kein Verfall',
    st_syla_27: 'nicht nur die Jahre',
    st_syla_28: 'etwas mit Absicht',
    st_syla_29: 'etwas Geplantes',
    st_syla_3: 'Mamas Tabellen und Papas Protokolle',
    st_syla_30: 'jede Wunde führt zu einem Punkt',
    st_syla_31: 'den jemand mit eigener Hand erreichen muss',
    st_syla_32: 'Dann sieht sie ihre eigene Mutter',
    st_syla_33: 'denselben Bericht erneut schreiben',
    st_syla_34: 'gleiche Worte, gleiche Hand, gleiche Stunde',
    st_syla_35: 'als hätte sie gerade erst begonnen',
    st_syla_36: 'und ihr Vater am Fenster',
